_CORE_SRC = '# Action format: "[(from_node, to_node, count), ...]" (a list of tuples).\n# Payout: "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# Cost: "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# Ownership persists without units; capture requires two consecutive strict leads.\n# Consequently capture value is a threshold, NOT a concave capacity-share payout.\n# The allocator below prices capture/defence bundles rather than incorrectly\n# assigning zero marginal value to the first unit of a multi-unit capture.\nimport time\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nUPKEEP = 2.0\n\n\ndef payout(values, owned, units_at_base):\n    """The specification\'s exact per-turn profit."""\n    return float(sum(v for v, own in zip(values, owned) if own)\n                 - UPKEEP * (20 - units_at_base))\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    lengths = {}\n    distance = [[10**6] * n for _ in range(n)]\n    for u in range(n):\n        distance[u][u] = 0\n    for u, v, length in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n        lengths[u, v] = lengths[v, u] = length\n        distance[u][v] = distance[v][u] = length\n    for row in adjacency:\n        row.sort()\n    for k in range(n):\n        for u in range(n):\n            for v in range(n):\n                candidate = distance[u][k] + distance[k][v]\n                if candidate < distance[u][v]:\n                    distance[u][v] = candidate\n    hops = [[-1] * n for _ in range(n)]\n    for u in range(n):\n        for v in range(n):\n            if u != v:\n                for w in adjacency[u]:\n                    if lengths[u, w] + distance[w][v] == distance[u][v]:\n                        hops[u][v] = w\n                        break\n    return adjacency, lengths, distance, hops\n\n\ndef legal_action(proposed, units, lengths, n):\n    """Validate against start-of-turn availability, never against arrivals."""\n    available = list(units)\n    grouped = {}\n    for source, destination, count in proposed:\n        source, destination, count = int(source), int(destination), int(count)\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if (source, destination) not in lengths:\n            continue\n        count = min(max(0, count), available[source])\n        if count:\n            available[source] -= count\n            key = (source, destination)\n            grouped[key] = grouped.get(key, 0) + count\n    return [(int(u), int(v), int(c))\n            for (u, v), c in sorted(grouped.items())]\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.records = []\n        self.bad_reports = 0\n\n    def _tokens(self, obs):\n        """Recover sticky goals, including goals beyond the current transit edge."""\n        turn = obs["turn"]\n        previous = {}\n        for node, arrival, goal in self.records:\n            key = (node, arrival if arrival > turn else 0)\n            previous.setdefault(key, []).append(goal)\n        tokens = []\n        for node, count in enumerate(obs["player_units"]):\n            key = (node, 0)\n            goals = previous.get(key, [])\n            for _ in range(count):\n                goal = goals.pop(0) if goals else obs["player_base"]\n                tokens.append((node, 0, goal))\n        for _, node, count, arrival in obs.get("player_transits", []):\n            key = (node, arrival)\n            goals = previous.get(key, [])\n            for _ in range(count):\n                goal = goals.pop(0) if goals else node\n                tokens.append((node, arrival, goal))\n        return tokens\n\n    def _plan(self, obs, tokens, deadline):\n        _, _, distance, _ = self.map_data\n        n = obs["n_nodes"]\n        turn = obs["turn"]\n        remaining = N_TURNS - turn\n        home = obs["player_base"]\n        enemy_home = obs["opponent_base"]\n        values = obs["node_value"]\n        owned = obs["player_owned"]\n        enemy_owned = obs["opponent_owned"]\n        enemy = list(obs["opponent_units"])\n        # Known imminent arrivals matter much more than hypothetical deployments.\n        for _, destination, count, arrival in obs.get("opponent_transits", []):\n            if arrival <= turn + 4:\n                enemy[destination] += count\n        goals = [home] * len(tokens)\n        free = list(range(len(tokens)))\n        pending = [v for v in range(n)\n                   if v not in (home, enemy_home) and\n                   (not owned[v] or enemy[v] > 0)]\n        while free and pending:\n            if time.perf_counter() >= deadline:\n                break\n            best = None\n            for target in pending:\n                need = enemy[target] if owned[target] else enemy[target] + 1\n                if need <= 0 or need > len(free):\n                    continue\n                ranked = []\n                for i in free:\n                    node, arrival, old_goal = tokens[i]\n                    delay = max(0, arrival - turn)\n                    travel = delay + distance[node][target]\n                    # Retargeting committed travellers must offer a clear improvement.\n                    stickiness = 0.0 if old_goal == target else (\n                        4.0 if arrival > turn else 1.0)\n                    ranked.append((travel + stickiness, travel, i))\n                ranked.sort()\n                selected = ranked[:need]\n                latest = max(x[1] for x in selected)\n                capture_offset = latest\n                if not owned[target] and latest == 0:\n                    capture_offset = 0 if obs["player_lead_turns"][target] else 1\n                earning_turns = max(0, remaining - capture_offset)\n                if earning_turns == 0:\n                    continue\n                multiplier = 2.0 if enemy_owned[target] or owned[target] else 1.0\n                benefit = multiplier * values[target] * earning_turns\n                if owned[target]:\n                    # Without defence, a stationary enemy captures in at most 2 turns.\n                    benefit = 2.0 * values[target] * max(0, remaining - max(1, latest))\n                if enemy[target]:\n                    # To keep the capture against a stationary opponent, the bundle\n                    # must remain deployed, paying upkeep every remaining turn.\n                    cost = UPKEEP * need * remaining\n                else:\n                    # Travel, synchronisation, the second lead, and the return home.\n                    # Returning units pay no upkeep on their final landing at home.\n                    return_distance = distance[target][home]\n                    cost = UPKEEP * sum(\n                        max(0, latest + 1 + return_distance - 1)\n                        for _ in selected)\n                    if latest == 0 and obs["player_lead_turns"][target]:\n                        cost = UPKEEP * need * return_distance\n                penalty = sum(max(0.0, rank - travel)\n                              for rank, travel, _ in selected)\n                net = benefit - cost - penalty\n                # Bundle marginal value per scarce deployed unit.\n                priority = net / (need ** 0.7)\n                candidate = (priority, net, -target, target, selected)\n                if net > 2.0 and (best is None or candidate[:3] > best[:3]):\n                    best = candidate\n            if best is None:\n                break\n            target, selected = best[3], best[4]\n            used = set()\n            for _, _, i in selected:\n                goals[i] = target\n                used.add(i)\n            free = [i for i in free if i not in used]\n            pending.remove(target)\n        return goals\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs.get("edges", []))\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0)):\n            self.bad_reports += 1\n        tokens = self._tokens(obs)\n        goals = self._plan(obs, tokens, deadline)\n        _, lengths, _, hops = self.map_data\n        turn = obs["turn"]\n        proposed = []\n        records = []\n        for (node, arrival, _), goal in zip(tokens, goals):\n            if arrival > turn:\n                records.append((node, arrival, goal))\n            elif node == goal:\n                records.append((node, 0, goal))\n            else:\n                hop = hops[node][goal]\n                if hop >= 0:\n                    proposed.append((node, hop, 1))\n                    records.append((hop, turn + lengths[node, hop], goal))\n                else:\n                    records.append((node, 0, goal))\n        action = legal_action(proposed, obs["player_units"], lengths, n)\n        if self.bad_reports >= 2:\n            # Extra conservative replay of already aggregated moves.\n            action = legal_action(action, obs["player_units"], lengths, n)\n        self.records = records\n        return action\n'
_CORE_CLASS = 'Strategy'
